; >S:DECODER; PUT "DECODER";; DECODES THE SCREEN NUMBER HELD; IN 'SCREEN' AND LEAVES THE; SCREEN IN THE BUFFER 'SCRBUF'; READY TO BE COPIED ONTO THE; SCREEN.;DECODE;LDA #0STA WORK+1 ;* CLEAR FROM LAST TIME;LDX SCREENLDA ROMNUM,XSTA WORK;; ACC = 0 TO 24;LDX #5;MULT;ASL WORKROL WORK+1;CPX #1BNE NOT32;LDA WORKSTA WORK+2LDA WORK+1STA WORK+3;NOT32;DEXBPL MULT;LDA WORKCLCADC WORK+2STA SELFMD+1;LDA WORK+1ADC WORK+3CLCADC #>SCDATA   ;* SCREEN DATASTA SELFMD+2;; SELFMD HAS BEEN SET UP (BY; SELF ALTERING CODE ) TO POINT; TO THE START OF THE COMPRESSED; DATA FOR THAT SCREEN.;;LDA #<SCRBUFSTA SLLDA #>SCRBUFSTA SL+1;LDX #0;LDA #23STA YCOUNT;LP1;LDA #3STA XCOUNT;LDA SLPHA;LDA SL+1PHA;LP2;SELFMD LDA $FFFF,X;LDY #0;LP3;ASL AROL WORK+2ASL AROL WORK+2;PHA;LDA WORK+2AND #3CLCADC #196    ;* BASE CHAR;STA (SL),Y;PLA;INYCPY #4BNE LP3;LDA SLCLCADC #4STA SL;LDA SL+1ADC #0STA SL+1;INX        ;* NEXT DATA;DEC XCOUNTBPL LP2;PLASTA SL+1;PLA;CLCADC #40STA SL;LDA SL+1ADC #0STA SL+1;DEC YCOUNTBPL LP1;LDA CLEARD   ;* CLEARED THIS ROOM?BEQ TUFLUK   ;* NO !;LDA #$00TAX;TONE1A;STA SCRBUF,XSTA SCRBUF+$100,XSTA SCRBUF+$200,XSTA SCRBUF+$2C0,X;INXBNE TONE1A;; CLEAR ALL CRAP;LDA #<SCRBUFSTA SLLDA #>SCRBUFSTA SL+1;LDY #15LDA #199     ;* BEST CHAR;TONE1;STA (SL),YDEYBPL TONE1    ;* ROOF;LDX #22      ;* NO. OF LINESLDY #0;TONE2;LDA #199STA (SL),Y;LDA SLCLCADC #40STA SL;LDA SL+1ADC #0STA SL+1;DEXBPL TONE2;; THATS THE LEFT SIDE (REMEMBER; THAT IT MIRROR'S IT LATER !);LDY #15LDA #199;TONE3;STA (SL),YDEYBPL TONE3;; CREATED A BLANK ROOM (I HOPE);TUFLUK;; NOW MIRROR IT;LDA #<SCRBUFSTA LMIRR+1STA RMIRR+1;LDA #>SCRBUFSTA LMIRR+2STA RMIRR+2;LDA #23STA YCOUNT;LP4;LDX #0LDY #31;LP5;LMIRR LDA $FFFF,XRMIRR STA $FFFF,Y;INXDEYCPY #15BNE LP5;LDA LMIRR+1CLCADC #40STA LMIRR+1STA RMIRR+1;LDA LMIRR+2ADC #0STA LMIRR+2STA RMIRR+2;DEC YCOUNTBPL LP4;; IT'S DONE - C'EST FINI !;; - NO !! PUT THE DOORS IN !;LDX SCREENLDA DOORDT,XSTA TEMP;LDX #200 ;* DOOR CHAR;AND #1BEQ NDR;STX SCRBUF+$1B8+31STX SCRBUF+$1E0+31;NDR;LDA TEMPAND #2BEQ NDL;STX SCRBUF+$1B8STX SCRBUF+$1E0;NDL;LDA TEMPAND #4BEQ NDU;STX SCRBUF+15STX SCRBUF+16;NDU;LDA TEMPAND #8BEQ NDD;STX SCRBUF+$398+$FSTX SCRBUF+$398+$10;NDD;;;RTS;;---------------------------;DOORDT;; DATA AS FOLLOWS :-;; BIT #76543210;;          DULR;.BYTE %00001001.BYTE %00001011.BYTE %00001011.BYTE %00001011.BYTE %00001010;.BYTE %00001101.BYTE %00001111.BYTE %00001111.BYTE %00001111.BYTE %00001110;.BYTE %00001101.BYTE %00001111.BYTE %00001111.BYTE %00001111.BYTE %00001110;.BYTE %00001101.BYTE %00001111.BYTE %00001111.BYTE %00001111.BYTE %00001110;.BYTE %00000101.BYTE %00000111.BYTE %00000111.BYTE %00000111.BYTE %00000110;;;;;.END